CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER) AS
  v_total  NUMBER := 0;
  v_max    NUMBER;
  v_newno  NUMBER;
  v_price  NUMBER;
  CURSOR c IS
    SELECT "No", "Grape", "Winery", "Price", "Score", "Cases"
      FROM "wine"
     WHERE "Score" >= arg1
       FOR UPDATE;
BEGIN
  FOR r IN c LOOP
    v_total := v_total + r."Price";
    IF instr(r."Grape", 'prefix_') = 1 THEN
      UPDATE "wine" SET "Price" = arg3 WHERE "No" = r."No";
    ELSIF r."No" < arg4 THEN
      DELETE FROM "wine" WHERE "No" = r."No";
    ELSIF r."Winery" = 'Twomey' THEN
      UPDATE "wine" SET "Price" = arg3 + r."Price" WHERE "No" = r."No";
    ELSIF r."Cases" > r."Score" THEN
      UPDATE "wine" SET "Price" = arg3 + r."Price" WHERE "No" = r."No";
    ELSE
      UPDATE "wine" SET "Price" = 3 * arg3 WHERE "No" = r."No";
    END IF;
  END LOOP;

  IF v_total > arg4 THEN
    v_price := arg3 + 1;
  ELSE
    v_price := arg3;
  END IF;

  SELECT MAX("No") INTO v_max FROM "wine";
  IF v_max IS NULL THEN
    v_newno := 1;
  ELSE
    v_newno := v_max + 1;
  END IF;

  INSERT INTO "wine" ("No", "Grape", "Score", "Price")
  VALUES (v_newno, 'prefix_' || arg2, arg1 + 1, v_price);
END;

